mapper.sql:
WHERE 1 = 1

   AND (
        UPPER(T1.SERVER_ID) LIKE '%' || UPPER(#{keyword}) || '%'
     OR UPPER(T1.SERVER_NAME) LIKE '%' || UPPER(#{keyword}) || '%'
     OR UPPER(NVL(T1.TECH_ROLE, '')) LIKE '%' || UPPER(#{keyword}) || '%'
     OR UPPER(NVL(T1.ENV_CD, '')) LIKE '%' || UPPER(#{keyword}) || '%'
     OR UPPER(NVL(T1.STATUS_CD, '')) LIKE '%' || UPPER(#{keyword}) || '%'
   )


   AND T1.SERVER_ID = #{serverId}


   AND T1.SERVER_NAME LIKE '%' || #{serverName} || '%'


   AND T1.TECH_ROLE = #{techRole}


   AND T1.ENV_CD = #{envCd}


   AND T1.STATUS_CD = #{statusCd}

mapper.select:
SELECT /* ifina1999S0_S0_exists */ COUNT(*)
  FROM TB_IF_SERVER_PILOT T1
 WHERE T1.SERVER_ID = #{serverId}

